import {React, useState} from "react";
import {useStateMachine} from "little-state-machine";
import {useNavigate, useParams} from "react-router-dom";
import './theme.css';
import './SurveyImgChoicePage.css';
import {decodeSurveyID} from "../core/generateSurvey";
import {DEFAULT_LANG, locale_text, locale_text_raw} from "./lang";
import {isRTLLang} from "../core/textdirection";


const Image = (opts) => {
    // Except the key shouldHighlight, copy all other keys from opts.
    const [isLoading, setIsLoading] = useState(true);
    const handleImageLoaded = () => {
        setIsLoading(false);
        // If opts contain didImageLoaded(), call it.
        if (opts['didImageLoaded']) {
            opts['didImageLoaded']();
        }
    };

    const {shouldSetGrey, shouldImageDisplayed, ...props} = opts;
    let className = "survey-image";
    if (shouldSetGrey) {
        className += " survey-image-grey";
    }
    // onLoad
    return (<div>
        {isLoading && (!shouldImageDisplayed || shouldImageDisplayed()) && <div className="spinner">
            {locale_text(opts['lang'], 'survey-img-choice-loading-text')} ...
        </div>}
        <img
            {...props}
            className={className}
            style={{display: isLoading ? 'none' : 'block'}}
            onLoad={handleImageLoaded}
        />
    </div>);
}

const ButtonImgPicker = (opts) => {
    const isSelected = opts["isSelected"];

    let className = "button-generic button-img-choice";
    if (isSelected) {
        className += " button-generic-selected";
    }
    // Make props to copy from opts except for key "isSelected"
    const {isSelected: _, ...props} = opts;
    return (<button className={className} {...props}></button>);
}

const SubmitButton = (opts) => {

    const {maxProgress, progress, lang, ...props} = opts;
    // console.log(maxProgress, progress);


    let divClasses = [];
    for (let i = 0; i < maxProgress; i++) {
        if (i < progress) {
            divClasses.push("progress-bar-item progress-bar-item-finished");
        } else {
            divClasses.push("progress-bar-item");
        }
    }
    let progressBar = (
        <div className="progress-bar">
            {divClasses.map((className, index) => {
                return (<div className={className} key={index}></div>);
            })}
        </div>
    );
    if (isRTLLang(lang)) {
        progressBar = (
            <div className="progress-bar-rtl" dir={"rtl"}>
                {divClasses.map((className, index) => {
                    return (<div className={className} key={index}></div>);
                })}
            </div>
        );
    }

    return (<>
        <button
            className="button-generic button-stick-to-right survey-image-choice-button-stick-to-right" {...props}>
        </button>

        {progressBar}
    </>);
}


const TextArea = (opts) => {
    const lang = opts['lang'] || DEFAULT_LANG;

    return (<textarea
        placeholder={locale_text_raw(lang, 'survey-img-choice-comment-placeholder')}
        className="textarea-comment-box"
        {...opts}
    >

        </textarea>);
}


export function SurveyImgChoicePage() {

    // Get parameters from the URL.
    // TODO: Decode survey id to get city and unique image sequence.
    const {surveyid} = useParams();
    const {city, surveyHash, imageSet} = decodeSurveyID(surveyid);

    // Add basic state variables
    const navigate = useNavigate();
    const {actions, state} = useStateMachine({
        simpleUpdate: (state, payload) => ({...state, ...payload})
    });
    const lang = state['language'] || DEFAULT_LANG;


    // Add basic state to ensure counter is updated.
    const [counter, setCounter] = useState(0);
    const [startTime, setStartTime] = useState(new Date());
    const [endTime, setEndTime] = useState(null);
    // console.log(startTime, endTime);

    let [leftImagePath, rightImagePath] = imageSet[counter].map((value) => {
        return `/images/${value}`
    });
    // console.log(leftImagePath, rightImagePath);

    // Add timer


    // Define field names to retrieve some properties.
    const formFieldCity = `${surveyid}/city`;
    const formFieldImageSelection = `${surveyid}/${counter}/selection`;
    const formFieldComment = `${surveyid}/${counter}/comment`;
    const formFieldDuration = `${surveyid}/${counter}/duration`;
    const formFieldStartTime = `${surveyid}/${counter}/start_time`;
    const formFieldEndTime = `${surveyid}/${counter}/end_time`;
    const formFieldLeftImagePath = `${surveyid}/${counter}/left_image_path`;
    const formFieldRightImagePath = `${surveyid}/${counter}/right_image_path`;

    // Add state to get selected button
    const [selectedButton, setSelectedButton] = useState(state[formFieldImageSelection] || null);
    const [commentTextValue, setCommentTextValue] = useState(state[formFieldComment] || '');

    // Define display properties
    const counterForDisplay = counter + 2;
    const isLeftButtonSelected = selectedButton === 'left';
    const isRightButtonSelected = selectedButton === 'right';
    const shouldLeftSetGrey = isRightButtonSelected && selectedButton !== null;
    const shouldRightSetGrey = isLeftButtonSelected && selectedButton !== null;
    const shouldDisplyCommentBox = selectedButton !== null;
    const MAX_COUNTER = 6;

    const isSubmitDisabled = ((!selectedButton) || (!commentTextValue));

    const buttonLeftOnClick = () => {
        // TODO: Value should be the image path
        setSelectedButton('left');
        setEndTime(new Date());
    };

    const buttonRightOnClick = () => {
        // TODO: Value should be the image path
        setSelectedButton('right');
        setEndTime(new Date());
    };

    const buttonSubmitOnClick = () => {
        // FIXME: Refactor this to use state machine.
        const new_counter = counter + 1;

        let formDict = {};
        formDict[formFieldImageSelection] = isLeftButtonSelected ? 'left' : 'right';
        formDict[formFieldComment] = commentTextValue;
        formDict[formFieldDuration] = (endTime - startTime);
        formDict[formFieldStartTime] = startTime;
        formDict[formFieldEndTime] = endTime;
        formDict[formFieldLeftImagePath] = leftImagePath;
        formDict[formFieldRightImagePath] = rightImagePath;
        formDict[formFieldCity] = city;

        // console.log(endTime - startTime);

        // Persist the survey record into the survey state.
        actions.simpleUpdate(formDict);
        // console.log(formDict);
        // Clear away current states.
        setSelectedButton(null);
        setCommentTextValue('');

        setStartTime(new Date());
        setEndTime(null);


        if (new_counter < MAX_COUNTER) {
            setCounter(new_counter);
        } else {
            navigate(`/surveyinfo/${surveyid}`)
        }

        // Clear away the loaded status of the images
        setLeftImageLoaded(false);
        setRightImageLoaded(false);

        // Scroll to top
        window.scrollTo(0, 0);
    }

    const textareaOnChange = (e) => {
        const value = e.target.value;
        setCommentTextValue(value);
    }

    let question2a = (
        <>
            <h1 className="title-text survey-image-title-text-h1">
                {counterForDisplay}a | {locale_text_raw(lang, 'survey-img-choice-title')}
            </h1>
        </>);
    if (isRTLLang(lang)) {
        question2a = (<>
            <h1 className="title-text survey-image-title-text-h1">
                <p dir={"rtl"}>
                    {counterForDisplay}a | {locale_text_raw(lang, 'survey-img-choice-title')}
                </p>
            </h1>
        </>);
    }

    let question2b = (<h1 className="title-text survey-image-title-text-h1">
        {counterForDisplay}b | {locale_text_raw(lang, "survey-img-choice-comment-box-question")}
    </h1>);
    if (isRTLLang(lang)) {
        question2b = (<h1 className="title-text survey-image-title-text-h1">
            <p dir={"rtl"}>
                {counterForDisplay}b | {locale_text_raw(lang, "survey-img-choice-comment-box-question")}
            </p>
        </h1>);
    }

    let [isLeftImageLoaded, setLeftImageLoaded] = useState(false);
    let [isRightImageLoaded, setRightImageLoaded] = useState(false);

    const didLeftImageLoaded = () => {
        setLeftImageLoaded(true);
    }
    const didRightImageLoaded = () => {
        setRightImageLoaded(true);
    }
    const shouldImageDisplayed = () => {
        console.log("shouldImageDisplayed", isLeftImageLoaded && isRightImageLoaded, isLeftImageLoaded, isRightImageLoaded)
        return isLeftImageLoaded && isRightImageLoaded;
    }


    return (<div className="container-page-mid-root">
        <div className="survey-block-image-picker">
            {question2a}
            {

                (shouldLeftSetGrey || shouldRightSetGrey) ?

                    (<div>
                        <div className="grid-item-image-picker-selected">
                            <Image src={shouldLeftSetGrey ? rightImagePath : leftImagePath}
                                   alt={shouldLeftSetGrey ? "right" : "left"}
                                   lang={lang}
                                   didImageLoaded={didLeftImageLoaded}
                            />
                        </div>
                    </div>) : (<div className="grid-container-image-picker">
                        <div className="grid-item-image-picker">
                            <Image shouldSetGrey={shouldLeftSetGrey}
                                   src={leftImagePath}
                                   alt="left"
                                   lang={lang}
                                   didImageLoaded={didRightImageLoaded}
                                   shouldImageDisplayed={shouldImageDisplayed}
                            />
                            <ButtonImgPicker
                                onClick={buttonLeftOnClick}
                                isSelected={isLeftButtonSelected}
                                disabled={shouldLeftSetGrey}
                            >
                                {locale_text(lang, "survey-img-choice-button-left")}
                            </ButtonImgPicker>
                        </div>
                        <div className="grid-item-image-picker">
                            <Image shouldSetGrey={shouldRightSetGrey}
                                   src={rightImagePath}
                                   alt="right"
                                   lang={lang}
                                   shouldImageDisplayed={shouldImageDisplayed}
                            />
                            <ButtonImgPicker
                                onClick={buttonRightOnClick}
                                isSelected={isRightButtonSelected}
                                disabled={shouldRightSetGrey}
                            >
                                {locale_text(lang, "survey-img-choice-button-right")}
                            </ButtonImgPicker>
                        </div>
                    </div>)

            }
        </div>
        {shouldDisplyCommentBox && (<>
            <div className="survey-block-comment">
                <br/>
                {question2b}
                <TextArea value={commentTextValue} onChange={textareaOnChange} lang={lang}></TextArea>
            </div>
            <SubmitButton
                onClick={buttonSubmitOnClick} disabled={isSubmitDisabled}
                maxProgress={MAX_COUNTER}
                progress={counter + 1}
                lang={lang}
            >
                {locale_text(lang, "survey-img-choice-submit-button")}
            </SubmitButton>
        </>)}


    </div>);
}
